const updateUniversity = `-- name: UpdateUniversity :execrows
UPDATE universities SET
    name      = coalesce($1, name),
    name_bn   = CASE WHEN $2::text IS NULL THEN name_bn ELSE NULLIF($2, '') END,
    city      = CASE WHEN $3::text IS NULL THEN city ELSE NULLIF($3, '') END,
    kind      = CASE WHEN $4::text IS NULL THEN kind ELSE NULLIF($4, '') END,
    website   = CASE WHEN $5::text IS NULL THEN website ELSE NULLIF($5, '') END,
    is_active = coalesce($6, is_active)
WHERE id = $7
`

type UpdateUniversityParams struct {
	Name     *string
	NameBn   *string
	City     *string
	Kind     *string
	Website  *string
	IsActive *bool
	ID       uuid.UUID
}

// Fields left NULL are kept; an empty string clears an optional one.
func (q *Queries) UpdateUniversity(ctx context.Context, arg UpdateUniversityParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateUniversity,
		arg.Name,
		arg.NameBn,
		arg.City,
		arg.Kind,
		arg.Website,
		arg.IsActive,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

