const userCounts = `-- name: UserCounts :one


SELECT count(*)::int AS total,
       (count(*) FILTER (WHERE verified_at IS NOT NULL))::int AS verified,
       (count(*) FILTER (WHERE verified_at IS NULL))::int AS not_verified,
       (count(*) FILTER (WHERE role = 'admin'))::int AS admins,
       (count(*) FILTER (WHERE blocked_at IS NOT NULL))::int AS blocked,
       (count(*) FILTER (WHERE created_at > $1::timestamptz))::int AS new_since
FROM users
`

type UserCountsRow struct {
	Total       int32
	Verified    int32
	NotVerified int32
	Admins      int32
	Blocked     int32
	NewSince    int32
}

// Superadmin panel. Reads across modules on purpose: the panel sees
// everything. Changes keep the same database rules the app relies on
// (a group keeps a CR, verified needs a university, domain guards).
// ---- dashboard --------------------------------------------------------------
func (q *Queries) UserCounts(ctx context.Context, since time.Time) (UserCountsRow, error) {
	row := q.db.QueryRow(ctx, userCounts, since)
	var i UserCountsRow
	err := row.Scan(
		&i.Total,
		&i.Verified,
		&i.NotVerified,
		&i.Admins,
		&i.Blocked,
		&i.NewSince,
	)
	return i, err
}

